type PrintField = CatalogPrintField;
interface DraftOverrides { initials: string; initialsInfix: string; name: string; backNumber: string; backNumberSizeClass: BackNumberSizeClass | ""; shortsNumber: string; }
interface DraftVariant { id: string; size: string; quantity: number; deviation: boolean; printChoice?: PrintField; overrides: DraftOverrides; }
