interface PendingProductionLine { id: string; type: ProductionLineType; content: string; sourceId: string; widthMm: number; heightMm: number; quantity: number; previewLabel: string; provenance: string; placementRole?: "INITIALS_FIRST" | "INITIALS_INFIX" | "INITIALS_LAST"; placementRule?: { compositionId: string; compositeText: string; segmentIndex: 0 | 1 | 2; segmentCount: 3; alignment: "CENTER" } }
