function composedInitialsLines(input: { id: string; initials: string; infix?: string; sourceId: string; widthMm: number; heightMm: number; quantity: number; provenance: string }): PendingProductionLine[] {
  const infix = String(input.infix ?? "").trim().toLocaleLowerCase("nl-NL");
  const normalizedInitials = input.initials.trim().toLocaleUpperCase("nl-NL");
  if (!infix) return [{ id: input.id, type: "INITIALS" as const, content: normalizedInitials, sourceId: input.sourceId, widthMm: input.widthMm, heightMm: input.heightMm, quantity: input.quantity, previewLabel: `Initialen ${normalizedInitials}`, provenance: input.provenance }];
  const characters = Array.from(normalizedInitials);
  if (characters.length !== 2) throw new Error("Een samengesteld tussenvoegsel vereist exact twee initialen.");
  const compositeText = `${characters[0]}${infix}${characters[1]}`; const compositionId = `${input.id}-initials-composite`;
  return [
    { role: "INITIALS_FIRST" as const, type: "INITIALS" as const, content: characters[0], segmentIndex: 0 as const },
    { role: "INITIALS_INFIX" as const, type: "TEXT" as const, content: infix, segmentIndex: 1 as const },
    { role: "INITIALS_LAST" as const, type: "INITIALS" as const, content: characters[1], segmentIndex: 2 as const },
  ].map((segment) => ({ id: `${input.id}-${segment.segmentIndex + 1}`, type: segment.type, placementRole: segment.role, content: segment.content, sourceId: input.sourceId, widthMm: 0, heightMm: 0, quantity: input.quantity, previewLabel: `Samengestelde initialen ${compositeText}`, provenance: `${input.provenance} · samengestelde initialen`, placementRule: { compositionId, compositeText, segmentIndex: segment.segmentIndex, segmentCount: 3 as const, alignment: "CENTER" as const } }));
}
