function fileAsBase64(file: File): Promise<string> { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(",")[1] ?? ""); reader.onerror = () => reject(new Error("Afbeelding kon niet worden gelezen.")); reader.readAsDataURL(file); }); }
function path(): string { const value = location.pathname.replace(/\/+$/, ""); return value === BASE || value === "" ? `${BASE}/overzicht` : value; }
function date(value: string | null | undefined): string { return value ? new Intl.DateTimeFormat("nl-NL", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" }).format(new Date(value)) : "Normale doorlooptijd"; }
function euro(value: number): string { return new Intl.NumberFormat("nl-NL", { style: "currency", currency: "EUR" }).format(value); }
function productionPill(order: WorkspaceOrder): string {
  const status = order.productionStatus ?? (order.stage === "DONE" ? "DONE" : order.stage === "PRINT" ? "IN_PRODUCTION" : "ATTENTION");
  const labels = { ATTENTION: "Aandacht nodig", READY: "Klaar om te produceren", IN_PRODUCTION: "In productie", DONE: "Gereed" } as const;
  return `<span class="sp-stage sp-stage--${status.toLowerCase().replace("_", "-")}">${labels[status]}</span>`;
}
function mailStatusLabel(status: string): string { return ({ NOT_SENT: "Nog niet vastgelegd", CAPTURED: "Vastgelegd", SMTP_ACCEPTED: "Verwerkt", SENT: "Verzonden", DELIVERED: "Bezorgd", FAILED: "Mislukt", UNKNOWN: "Controleren", BOUNCED: "Niet bezorgd" } as Record<string, string>)[status] ?? status; }
function storeStatus(order: WorkspaceOrder): { label: string; tone: string } {
  if (order.pickup?.status === "PICKED_UP") return { label: "Opgehaald", tone: "picked-up" };
  if (order.stage === "DONE" && ["SENT", "DELIVERED"].includes(order.communication?.ready.status ?? "")) return { label: "Klant geïnformeerd", tone: "informed" };
  if (order.stage === "DONE") return { label: "Klaar", tone: "ready" };
  return { label: "In behandeling", tone: "active" };
}
function storePill(order: WorkspaceOrder): string { const status = storeStatus(order); return `<span class="sp-store-status sp-store-status--${status.tone}">${status.label}</span>`; }
function productionAttentionCopy(order: WorkspaceOrder): string {
  if (order.items.some((item) => item.productionReadiness?.status === "DATA_GAP" || item.backNumberProduction?.status === "DATA_GAP")) return "Productiegegevens of fysieke maat controleren";
  if (order.attention && !/(pilot|workspace|positie|referentieafstand|rotatie|spiegeling)/iu.test(order.attention)) return order.attention;
  return "Productie-instructie controleren";
}
