function productionFonts(state: PilotBootstrap): string {
  if (!["admin", "operator"].includes(state.currentUser.role)) return empty("Geen toegang");
  const upload = state.currentUser.role !== "admin"
    ? `<p>Alleen een bevoegde beheerder kan een productie-font toevoegen.</p>`
    : state.capabilities.fontUploadsEnabled
      ? `<form data-production-font-form><label>Productienaam<input name="name" required maxlength="120"></label><label>TTF, OTF, WOFF of WOFF2<input name="fontFile" type="file" accept=".ttf,.otf,.woff,.woff2,font/ttf,font/otf,font/woff,font/woff2" required></label><label>Herkomst en licentie<textarea name="provenance" rows="3" required></textarea></label><label><input type="checkbox" name="allowedInStore" checked> Beschikbaar voor Vrije bedrukking in Winkel</label><button class="sp-button sp-button--primary">Technisch valideren en toevoegen</button><small>Handtekening, extensie, maximale grootte en hash worden server-side gecontroleerd. Toevoegen bewijst nog geen fysieke snijuitkomst.</small></form>`
      : `<p>Fontuploads zijn in deze omgeving uitgeschakeld.</p>`;
  return `<a class="sp-back" data-link href="${BASE}/productie">← Productie</a>${head("BEHEERDE PRODUCTIEBRONNEN", "Fontbibliotheek", "Een begrensde bibliotheek. Preview en jobsnapshot gebruiken exact dezelfde bronversie; er is geen systeemfontfallback.")}<div class="sp-font-library"><section class="sp-panel"><p class="sp-eyebrow">BESCHIKBARE FONTS</p><h2>${state.productionFonts.length} bron${state.productionFonts.length === 1 ? "" : "nen"}</h2>${state.productionFonts.map((font) => `<article class="sp-font-source"><div><strong>${esc(font.name)}</strong><span>${esc(font.originalFilename)} · ${font.sizeBytes} bytes</span><small>${esc(font.provenance)}</small></div><dl><div><dt>Versie</dt><dd>${esc(font.version)}</dd></div><div><dt>SHA-256</dt><dd><code>${esc(font.sha256)}</code></dd></div><div><dt>Status</dt><dd>${esc(font.status)}</dd></div><div><dt>Winkel</dt><dd>${font.allowedInStore ? "Toegestaan" : "Alleen Productie"}</dd></div></dl></article>`).join("")}</section><section class="sp-panel"><p class="sp-eyebrow">BEVOEGDE UPLOAD</p><h2>Fontbron toevoegen</h2>${upload}</section></div>`;
}

function teamOrderProductionFirst(state: PilotBootstrap): string {
  const associations = associationNames(state);
  if (!teamAssociation || !associations.includes(teamAssociation)) teamAssociation = associations[0] ?? "";
  const profiles = state.productionProfiles.filter(({ id }) => id !== "profile-none");
  const prepared = teamPreparedRows.length ? `<section class="sp-panel sp-flow-section"><div class="sp-step"><b>3</b><div><p class="sp-eyebrow">CONTROLEREN</p><h2>${teamPreparedRows.length} productieregels</h2><p>Corrigeer alleen afwijkingen; de invoer blijft één teamorder.</p></div></div><div class="sp-team-prepared">${teamPreparedRows.map((row, index) => `<div class="sp-team-row sp-team-row--prepared sp-team-row--production"><b>${index + 1}</b><label>Naam/context<input data-team-row-field="participantName" data-team-row-id="${row.id}" value="${esc(row.participantName)}"></label><span><strong>${esc(printLabels[row.kind ?? "backNumber"])} ${esc(row.value)}</strong><small>${esc(state.productionProfiles.find(({ id }) => id === row.profileId)?.name ?? "Profiel ontbreekt")}</small></span><label>Maat<input data-team-row-field="size" data-team-row-id="${row.id}" value="${esc(row.size)}"></label>${row.kind === "initials" ? `<label>Tussenvoegsel (optioneel)<input data-team-row-field="initialsInfix" data-team-row-id="${row.id}" value="${esc(row.initialsInfix ?? "")}"></label>` : ""}<label>Aantal<input type="number" min="1" max="9" data-team-row-field="quantity" data-team-row-id="${row.id}" value="${row.quantity}"></label><button type="button" data-action="remove-team-row" data-team-row-id="${row.id}">Verwijder</button></div>`).join("")}</div></section>` : "";
  return `<a class="sp-back" data-link href="${BASE}/orders/nieuw">← Nieuwe order</a>${head("TEAMORDER · PRODUCTIE-EERST", "Teamorder", "Voer alleen de benodigde productiegegevens in. Een artikel- of webshopselectie is niet verplicht.")}<form class="sp-capability-form" data-team-order-form><section class="sp-panel sp-flow-section"><div class="sp-step"><b>1</b><div><p class="sp-eyebrow">KLANT & TEAM</p><h2>Groepsinformatie</h2></div></div><div class="sp-form-grid"><label>Naam contactpersoon (optioneel)<input name="customer"></label><label>E-mail (optioneel)<input name="customerEmail" type="email"></label><label>Telefoon (optioneel)<input name="customerPhone" type="tel"></label><label>Vereniging<select name="teamAssociation" data-team-association>${associations.map((association) => `<option value="${esc(association)}" ${association === teamAssociation ? "selected" : ""}>${esc(association)}</option>`).join("")}</select></label></div></section><section class="sp-panel sp-flow-section"><div class="sp-step"><b>2</b><div><p class="sp-eyebrow">PRODUCTIEREGELS</p><h2>Wat moet er gemaakt worden?</h2><p>Gebruik losse waarden, reeksen of herhalingen. Voorbeelden: <strong>1 t/m 9</strong>, <strong>34</strong>, <strong>nummer 3 twee keer</strong>, <strong>DW x 2</strong>.</p></div></div><div class="sp-form-grid"><label>Soort<select name="teamProductionKind"><option value="backNumber">Rugnummer</option><option value="shortsNumber">Shortnummer</option><option value="initials">Initialen</option><option value="name">Naam</option></select></label><label>Productieprofiel<select name="teamProductionProfile" required>${profiles.map((profile) => `<option value="${esc(profile.id)}">${esc(profile.name)} · ${esc(profile.sizeLabel)}</option>`).join("")}</select></label><label>Kledingmaat (optioneel)<input name="teamDefaultSize"></label><label>Tussenvoegsel (optioneel, bij initialen)<input name="teamInitialsInfix" maxlength="8" placeholder="bijv. vd"></label></div><label>Waarden<textarea name="teamProductionLines" rows="5" required placeholder="1 t/m 9&#10;34&#10;nummer 3 twee keer"></textarea></label><button class="sp-button sp-button--primary" type="button" data-action="prepare-team-production">Productieregels voorbereiden</button><small>Geen fictieve SKU's: deze regels worden als handmatige teamproductie met expliciete provenance opgeslagen.</small></section>${prepared}<section class="sp-panel sp-checkout-summary"><p class="sp-eyebrow">OPSLAAN</p><h2>Teamorder controleren</h2><p>${teamPreparedRows.length ? `${teamPreparedRows.reduce((sum, row) => sum + row.quantity, 0)} stuks · ${teamPreparedRows.length} productieregels` : "Bereid eerst de productieregels voor."}</p><button class="sp-button sp-button--primary" type="submit" ${teamPreparedRows.length ? "" : "disabled"}>Teamorder opslaan</button></section></form>`;
}

function teamOrder(state: PilotBootstrap): string {
  return teamOrderProductionFirst(state);
  const associations = [...new Set(state.articles.filter(({ active }) => active).filter(isBedrukkingRelevant).map(({ association }) => association))].sort((left, right) => left.localeCompare(right, "nl"));
  if (!teamAssociation || !associations.includes(teamAssociation)) teamAssociation = associations[0] ?? "";
  const articles = state.articles.filter(({ active, association }) => active && association === teamAssociation).filter(isBedrukkingRelevant);
  const articleCards = articles.map((article) => { const fields = articleFields(article); return `<label class="sp-team-article${teamSelectedArticles.has(article.id) ? " is-selected" : ""}"><input type="checkbox" data-team-article value="${esc(article.id)}" ${teamSelectedArticles.has(article.id) ? "checked" : ""}><img src="${articleImage(article.imageKey)}" alt=""><span><strong>${esc(article.name)}</strong><small>${fields.length ? fields.map((field) => printLabels[field]).join(" · ") : "Productie-inrichting volgt"}</small>${article.validation?.status === "VALIDATED" ? "" : `<em class="sp-validation-badge sp-validation-badge--gap">${esc(article.validation?.status ?? "DATA_GAP")}</em>`}</span></label>`; }).join("");
  const prepared = teamPreparedRows.length ? `<section class="sp-panel sp-flow-section"><div class="sp-step"><b>3</b><div><p class="sp-eyebrow">CONTROLEREN</p><h2>${teamPreparedRows.length} artikelregels voorbereid</h2><p>Pas alleen een afwijking aan. Eén speler kan meerdere artikelregels hebben.</p></div></div><div class="sp-team-prepared">${teamPreparedRows.map((row, index) => { const article = state.articles.find(({ id }) => id === row.articleId)!; return `<div class="sp-team-row sp-team-row--prepared"><b>${index + 1}</b><label>Speler<input name="teamName:${row.id}" data-team-row-field="participantName" data-team-row-id="${row.id}" value="${esc(row.participantName)}"></label><span class="sp-team-row__article"><img src="${articleImage(article.imageKey)}" alt=""><strong>${esc(article.name)}</strong></span><label>Maat${garmentSizeControl(article, `teamSize:${row.id}`, row.size, `data-team-row-field="size" data-team-row-id="${row.id}"`)}</label><label>Aantal<input type="number" min="1" max="9" name="teamQuantity:${row.id}" data-team-row-field="quantity" data-team-row-id="${row.id}" value="${row.quantity}"></label>${article.supports.includes("initials") && teamPrintFields.has("initials") ? `<label>Initialen<input name="teamInitials:${row.id}" data-team-row-field="initials" data-team-row-id="${row.id}" value="${esc(row.initials)}"></label>` : ""}${article.supports.includes("backNumber") && teamPrintFields.has("backNumber") ? `<label>Rugnummer<input name="teamBack:${row.id}" data-team-row-field="backNumber" data-team-row-id="${row.id}" value="${esc(row.backNumber)}"></label><label>Klasse<select name="teamClass:${row.id}" data-team-row-field="backNumberSizeClass" data-team-row-id="${row.id}"><option value="SENIOR" ${row.backNumberSizeClass === "SENIOR" ? "selected" : ""}>Senior</option><option value="JUNIOR" ${row.backNumberSizeClass === "JUNIOR" ? "selected" : ""}>Junior · geblokkeerd zolang fysieke mm ontbreekt</option></select></label>` : ""}${article.supports.includes("shortsNumber") && teamPrintFields.has("shortsNumber") ? `<label>Shortnummer<input name="teamShort:${row.id}" data-team-row-field="shortsNumber" data-team-row-id="${row.id}" value="${esc(row.shortsNumber)}"></label>` : ""}<button type="button" data-action="remove-team-row" data-team-row-id="${row.id}">Verwijder</button></div>`; }).join("")}</div><button class="sp-button sp-button--secondary" type="button" data-action="add-team-row">+ Speler/artikel toevoegen</button></section>` : "";
  return `<a class="sp-back" data-link href="${BASE}/orders/nieuw">← Nieuwe order</a>${head("TEAMORDER", "Teamorder", "Leg eerst de groep vast. Workspace maakt daarna alleen de regels die nodig zijn.")}<form class="sp-capability-form" data-team-order-form><section class="sp-panel sp-flow-section"><div class="sp-step"><b>1</b><div><p class="sp-eyebrow">KLANT & TEAM</p><h2>Groepsinformatie</h2></div></div><div class="sp-form-grid"><label>Naam contactpersoon<input name="customer" required></label><label>E-mail<input name="customerEmail" type="email" required></label><label>Telefoon<input name="customerPhone" type="tel" required></label><label>Vereniging<select name="teamAssociation" data-team-association>${associations.map((association) => `<option ${association === teamAssociation ? "selected" : ""}>${esc(association)}</option>`).join("")}</select></label></div></section><section class="sp-panel sp-flow-section"><div class="sp-step"><b>2</b><div><p class="sp-eyebrow">ARTIKELEN & REEKS</p><h2>Welke artikelen heeft het team nodig?</h2><p>Kies live artikelen en maak bijvoorbeeld rugnummers 1 t/m 18. Ontbrekende productie-inrichting blijft zichtbaar bij Productie.</p></div></div><div class="sp-team-articles">${articleCards || `<p>Voor deze vereniging zijn nog geen live artikelen lokaal vastgelegd.</p>`}</div><fieldset class="sp-team-print-types"><legend>Gewenste bedrukking</legend>${(["initials", "backNumber", "shortsNumber"] as PrintField[]).map((field) => `<label><input type="checkbox" data-team-print-field value="${field}" ${teamPrintFields.has(field) ? "checked" : ""}> ${printLabels[field]}</label>`).join("")}</fieldset><div class="sp-form-grid sp-form-grid--compact"><label>Vanaf nummer<input name="teamStart" type="number" min="0" max="999" value="1"></label><label>Tot en met<input name="teamEnd" type="number" min="0" max="999" value="18"></label><label>Standaardmaat<input name="teamDefaultSize" value="M"></label><label>Standaardinitialen (optioneel)<input name="teamDefaultInitials" maxlength="8"></label><label>Rugnummerklasse<select name="teamDefaultClass"><option value="SENIOR">Senior</option><option value="JUNIOR">Junior · geblokkeerd</option></select></label></div><button class="sp-button sp-button--primary" type="button" data-action="prepare-team">Regels voorbereiden</button></section>${prepared}<section class="sp-panel sp-checkout-summary"><p class="sp-eyebrow">OPSLAAN</p><h2>Teamorder controleren</h2><p>${teamPreparedRows.length ? `${teamPreparedRows.length} artikelregels · ${teamSelectedArticles.size} artikeltypen` : "Bereid eerst de teamregels voor."}</p><button class="sp-button sp-button--primary" type="submit" ${teamPreparedRows.length ? "" : "disabled"}>Teamorder opslaan</button></section></form>`;
}

function associationAdminV3(state: PilotBootstrap): string {
  if (!canAccessAdmin(state)) return empty("Geen toegang");
  const selected = activeAssociation && state.associations.some(({ name }) => name === activeAssociation) ? activeAssociation : state.associations[0]?.name ?? ""; activeAssociation = selected;
  const association = state.associations.find(({ name }) => name === selected); if (!association) return empty("Vereniging niet gevonden");
  const articles = state.articles.filter((article) => article.association === selected);
  const dims = association.dimensionsCm;
  return `<a class="sp-back" data-link href="${BASE}/beheer">← Beheer</a>${head("VERENIGINGEN", "Sportpaleis-inrichting", "Brongegevens zijn zichtbaar; ontbrekende catalogi en maten blijven expliciet onbekend.")}<div class="sp-association-admin-layout"><aside class="sp-panel sp-association-admin-list"><label><span class="sp-visually-hidden">Zoek vereniging</span><input type="search" data-association-search placeholder="Zoek vereniging"></label><div>${state.associations.map(({ name }) => `<button type="button" data-action="select-association" data-association="${esc(name)}" data-association-option="${esc(name.toLowerCase())}" class="${name === selected ? "is-active" : ""}">${associationMark(state, name)}<span>${esc(name)}</span></button>`).join("")}</div></aside><section class="sp-panel sp-association-detail"><div class="sp-association-admin__head">${associationMark(state, selected)}<div><p class="sp-eyebrow">VERENIGING</p><h2>${esc(selected)}</h2><span>${articles.length} gevalideerde/overgenomen artikelen</span></div></div><dl class="sp-config-grid"><div><dt>Letterprofiel</dt><dd>${esc(association.fontProfile || "Onbekend")}</dd></div><div><dt>Foliekleur</dt><dd>${esc(association.foilColors.join(" / ") || "Onbekend")}</dd></div><div><dt>Initialen shirt</dt><dd>${dims.initialsShirt ?? "Onbekend"} ${dims.initialsShirt ? "cm" : ""}</dd></div><div><dt>Senior rugnummer</dt><dd>${dims.backNumberSenior ?? "Onbekend"} ${dims.backNumberSenior ? "cm" : ""}</dd></div><div class="is-gap"><dt>Junior rugnummer</dt><dd>DATA_GAP · fysieke maat niet bevestigd</dd></div><div><dt>Shortnummer</dt><dd>${dims.shortsNumber ?? "Onbekend"} ${dims.shortsNumber ? "cm" : ""}</dd></div></dl><p>${esc(association.notes || "Geen aanvullende bronnotitie.")}</p><p class="sp-source">Bron: ${esc(association.source.file)} · ${esc(association.source.sheet)}!${esc(association.source.range)}</p><div class="sp-association-articles">${articles.map((article) => `<article><img src="${articleImage(article.imageKey)}" alt=""><div><strong>${esc(article.name)}</strong><span>${esc(article.articleNumber)} · ${article.active ? "beschikbaar" : "verborgen"}</span></div></article>`).join("") || `<div class="sp-data-gap-note"><strong>Artikelcatalogus nog niet gevalideerd</strong><span>Er worden geen producten, afbeeldingen, SKU's of prijzen verzonnen.</span></div>`}</div></section></div>`;
}

function associationProductionForm(association: AssociationConfiguration): string {
  const dims = association.dimensionsCm;
  const number = (name: string, value: number | null) => `<input name="${name}" type="number" step="0.1" min="0.1" max="100" value="${value ?? ""}" placeholder="Onbekend">`;
  return `<form class="sp-association-edit" data-association-production-form data-association-id="${esc(association.id)}"><input type="hidden" name="expectedRevision" value="${association.revision ?? 1}"><p class="sp-eyebrow">PRODUCTIE-INSTELLINGEN</p><label>Letterprofiel<input name="fontProfile" value="${esc(association.fontProfile)}" required></label><label>Foliekleuren <small>komma-gescheiden</small><input name="foilColors" value="${esc(association.foilColors.join(", "))}" required></label><div class="sp-form-grid sp-form-grid--compact"><label>Initialen shirt (cm)${number("initialsShirt", dims.initialsShirt)}</label><label>Senior rugnummer (cm)${number("backNumberSenior", dims.backNumberSenior)}</label><label>Borstnummer (cm)${number("chestNumber", dims.chestNumber)}</label><label>Shortnummer (cm)${number("shortsNumber", dims.shortsNumber)}</label><label>Naamhoogte (cm)${number("nameHeight", dims.nameHeight)}</label></div><label>Junior kledingmaten <small>komma-gescheiden</small><input name="juniorGarmentSizes" value="${esc((association.juniorGarmentSizes ?? []).join(", "))}" placeholder="116, 128, 140, 152, 164"></label><button class="sp-button sp-button--primary">Productie-instellingen opslaan</button><small>Versie ${association.revision ?? 1} · het productievoorstel leest deze verenigingswaarden direct.</small></form>`;
}

function userAdminV3(state: PilotBootstrap): string {
  if (!canAccessAdmin(state)) return empty("Geen toegang");
  return `<a class="sp-back" data-link href="${BASE}/beheer">← Beheer</a><nav class="sp-people-tabs" aria-label="Mensenbeheer"><a class="is-active" data-link href="${BASE}/beheer/gebruikers">Gebruikers</a><a data-link href="${BASE}/beheer/werknemers">Werknemers</a></nav>${head("GEBRUIKERS", "Gebruikers", "Nodig veilig uit en bepaal de rol. De activatielink wordt één keer lokaal getoond.")}<div class="sp-user-capability-layout"><form class="sp-panel" data-invite-user-form><p class="sp-eyebrow">NIEUWE GEBRUIKER</p><h2>Uitnodigen</h2><label>Naam<input name="name" required></label><label>E-mailadres<input name="email" type="email" required></label><label>Rol<select name="role"><option value="store">Winkelmedewerker</option><option value="operator">Productie</option><option value="admin">Beheerder</option></select></label><button class="sp-button sp-button--primary">Activatielink maken</button><p class="sp-muted">Geen mail wordt verstuurd. De code verloopt na 24 uur en wordt alleen gehasht opgeslagen.</p><div data-activation-result></div></form><section class="sp-panel"><p class="sp-eyebrow">TOEGANG</p><h2>${state.users.length} gebruikers</h2><div class="sp-user-list sp-user-list--overview">${state.users.map((user) => `<article><span class="sp-user__avatar">${esc(user.initials)}</span><div><strong>${esc(user.name)}</strong><span>${esc(user.email)}</span></div><span><small>Rol</small><strong>${esc(roleName(user.role))}</strong></span><span><small>Toegang</small><strong>${esc(user.status)}</strong></span><a class="sp-button sp-button--secondary" data-link href="${BASE}/beheer/gebruikers/${user.id}">Beheren</a></article>`).join("")}</div></section></div>`;
}

function employeeAdmin(state: PilotBootstrap): string {
  if (!canAccessAdmin(state)) return empty("Geen toegang");
  const employees = state.employees ?? [];
  const form = (employee?: (typeof employees)[number]) => `<form class="sp-panel sp-employee-form" data-employee-form ${employee ? `data-employee-id="${esc(employee.id)}"` : ""}><input type="hidden" name="expectedRevision" value="${employee?.revision ?? ""}"><div><label>Werknemer<input name="name" required maxlength="120" value="${esc(employee?.name ?? "")}"></label><label>Verkoopnummer<input name="salesNumber" required inputmode="numeric" pattern="[0-9]{1,8}" maxlength="8" value="${esc(employee?.salesNumber ?? "")}"></label><label>Workspace-toegang (optioneel)<select name="userId"><option value="">Geen login gekoppeld</option>${state.users.map((user) => `<option value="${esc(user.id)}" ${employee?.userId === user.id ? "selected" : ""}>${esc(user.name)} · ${esc(user.email)}</option>`).join("")}</select></label><label class="sp-check"><input type="checkbox" name="active" ${employee?.active !== false ? "checked" : ""}> Actief</label></div><button class="sp-button ${employee ? "sp-button--secondary" : "sp-button--primary"}">${employee ? "Werknemer opslaan" : "Werknemer toevoegen"}</button></form>`;
  return `<a class="sp-back" data-link href="${BASE}/beheer">← Beheer</a><nav class="sp-people-tabs" aria-label="Mensenbeheer"><a data-link href="${BASE}/beheer/gebruikers">Gebruikers</a><a class="is-active" data-link href="${BASE}/beheer/werknemers">Werknemers</a></nav>${head("WERKNEMERS", "Werknemers en verkoopnummers", "Een werknemer hoeft geen Workspace-login te hebben. Orders bewaren altijd de gekozen werknemer als historische snapshot.")}<section class="sp-employee-list">${employees.map((employee) => form(employee)).join("") || `<div class="sp-panel"><p>Nog geen werknemersrecords.</p></div>`}</section><section><h2>Werknemer toevoegen</h2>${form()}</section><p class="sp-safe-note"><strong>Beveiligde personeelsgegevens vallen buiten deze pilot.</strong> Contracten en personeelsdocumenten horen later in een afzonderlijke admin-only laag.</p>`;
}

function activationPage(message = ""): string { document.title = "Account activeren — Sportpaleis Workspace"; return `<main class="sp-login"><section class="sp-login__brand"><img class="sp-login__logo" src="${SPORTPALEIS_OFFICIAL_LOGO}" alt="Sport 2000 Sportpaleis"><p>Activeer uw persoonlijke Sportpaleis-account.</p></section><section class="sp-login__panel"><form data-activation-form><p class="sp-eyebrow">ACCOUNT ACTIVEREN</p><h1>Kies een wachtwoord</h1>${message ? `<div class="sp-form-error">${esc(message)}</div>` : ""}<label>Nieuw wachtwoord<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label>Herhaal wachtwoord<input name="passwordConfirm" type="password" minlength="12" required autocomplete="new-password"></label><button class="sp-button sp-button--primary sp-button--wide">Account activeren</button><p>De link is eenmalig en verloopt na 24 uur.</p></form></section></main>`; }

function context(): string { return `${head("CONTEXT", "Werken vanuit dezelfde bron", "Korte, actuele afspraken.")}<div class="sp-doc-grid"><article class="sp-panel"><h2>Klantorder is leidend</h2><p>Vereniging is de eerste artikelcontext; meerdere verenigingen blijven samen in één klantorder.</p></article><article class="sp-panel"><h2>Kledingmaat ≠ bedrukmaat</h2><p>Het beheerde productieprofiel bepaalt formaat en positie.</p></article><article class="sp-panel"><h2>450 mm absoluut</h2><p>Automatische indeling gebruikt 440 mm en schaalt nooit.</p></article><article class="sp-panel"><h2>CID-authority</h2><p>CID Manual 2025 bepaalt de huisstijl; logo-overzicht 2026 de Sportpaleis-variant.</p></article></div>`; }
function feedback(state: PilotBootstrap): string {
  return `${head("FEEDBACK", "Leg het vast waar je het ziet", "Pagina, gebruiker, tijdstip en release worden automatisch meegenomen.")}<form class="sp-panel sp-form" data-feedback-form><label>Categorie<select name="category"><option>Vraag</option><option>Verbetering</option><option>Probleem</option></select></label><label>Module<select name="module"><option>Orders</option><option>Productie</option><option>Beheer</option></select></label><label>Beschrijving<textarea name="description" required rows="5"></textarea></label><label>Screenshot of foto (optioneel)<input name="attachments" type="file" accept="image/png,image/jpeg,image/webp" multiple><small>PNG, JPG of WebP · maximaal 3 bestanden van 5 MB</small></label><button class="sp-button sp-button--primary">Vastleggen</button><p>${state.feedback.length} items zichtbaar voor jouw rol.</p></form>`;
}
function empty(title: string): string { return `<section class="sp-empty"><h1>${esc(title)}</h1><a class="sp-button sp-button--primary" data-link href="${BASE}/overzicht">Terug</a></section>`; }

// Behoud de vorige renderers als expliciete regressiereferentie; V3 gebruikt de bronrijke varianten hieronder.
void userAdmin;
void associationAdmin;
void webshop;
void operatorSettings;
void customOrder;

function page(state: PilotBootstrap, current: string): { title: string; html: string } {
  const contexts = new Set(state.capabilities.workContexts ?? state.currentUser.workContexts ?? []);
  if (state.currentUser.role === "store" && (current.startsWith(`${BASE}/productie`) || current.startsWith(`${BASE}/beheer`) || current === `${BASE}/context` || current === `${BASE}/feedback` || current === `${BASE}/voorkeuren`)) return { title: "Geen toegang", html: empty("Deze pagina hoort niet bij de winkelrol") };
  if (current === `${BASE}/overzicht`) return { title: "Overzicht", html: overview(state) };
  if (current === `${BASE}/winkel`) return contexts.has("STORE") ? { title: "Winkel", html: winkel(state) } : { title: "Geen toegang", html: empty("Winkelcontext is niet toegestaan") };
  if (current === `${BASE}/webshop`) return contexts.has("WEBSHOP") ? { title: "Webshop", html: webshopImport(state) } : { title: "Geen toegang", html: empty("Webshopcontext is niet toegestaan") };
  if (current === `${BASE}/alles`) return contexts.has("ALL") ? { title: "Alles", html: allWorkspace(state) } : { title: "Geen toegang", html: empty("Organisatiebreed zoeken is niet toegestaan") };
  if (current === `${BASE}/orders`) return { title: "Orders", html: orders(state) };
  if (current === `${BASE}/orders/team`) return ["admin", "operator"].includes(state.currentUser.role) ? { title: "Teamorder", html: teamOrder(state) } : { title: "Geen toegang", html: empty("Teamorder en logo's horen bij Productie") };
  if (current === `${BASE}/orders/eigen-artikel`) return { title: "Vrije opdruk", html: freePrintingOrder(state) };
  if (current === `${BASE}/orders/nieuw`) return { title: "Bedrukken", html: newOrder(state) };
  if (current.startsWith(`${BASE}/orders/`)) return { title: "Orderdetail", html: orderDetail(state, decodeURIComponent(current.slice(`${BASE}/orders/`.length))) };
  if (current === `${BASE}/productie`) return { title: "Productie", html: production(state) };
  if (current === `${BASE}/productie/historie`) return { title: "Plot-/printhistorie", html: productionHistory(state) };
  if (current.startsWith(`${BASE}/productie/voorstellen/`)) return { title: "Productievoorstel", html: persistedProductionProposal(state, decodeURIComponent(current.slice(`${BASE}/productie/voorstellen/`.length))) };
  if (current.startsWith(`${BASE}/productie/historie/`)) return { title: "Productiejob", html: productionJobDetail(state, decodeURIComponent(current.slice(`${BASE}/productie/historie/`.length))) };
  if (current === `${BASE}/productie/elementen`) return { title: "Productie-elementen", html: productionElements(state) };
  if (current === `${BASE}/productie/fonts`) return { title: "Fontbibliotheek", html: productionFonts(state) };
  if (current === `${BASE}/productie/voorstel`) return { title: "Productievoorstel", html: productionProposal(state) };
  if (current === `${BASE}/productie/instellingen`) return { title: "Technische profielen", html: profileAdmin(state, true) };
  if (current === `${BASE}/context`) return { title: "Context", html: context() };
  if (current === `${BASE}/feedback`) return { title: "Feedback", html: feedback(state) };
  if (current === `${BASE}/voorkeuren`) return { title: "Mijn weergave", html: preferences(state) };
  if (current === `${BASE}/beheer`) return { title: "Beheer", html: adminHomeV2(state) };
  if (current === `${BASE}/beheer/gebruikers`) return { title: "Gebruikers", html: userAdminV3(state) };
  if (current === `${BASE}/beheer/werknemers`) return { title: "Werknemers", html: employeeAdmin(state) };
  if (current.startsWith(`${BASE}/beheer/gebruikers/`)) return { title: "Gebruiker beheren", html: userDetail(state, decodeURIComponent(current.slice(`${BASE}/beheer/gebruikers/`.length))) };
  if (current === `${BASE}/beheer/artikelen`) return { title: "Artikelbeheer", html: articleAdmin(state) };
  if (current === `${BASE}/beheer/verenigingen`) return { title: "Verenigingen", html: associationAdminV3(state) };
  if (current === `${BASE}/beheer/productieprofielen`) return { title: "Productieprofielen", html: profileAdmin(state) };
  if (current === `${BASE}/beheer/folie`) return { title: "Folie & rollen", html: foilAdmin(state) };
  if (current === `${BASE}/beheer/commercieel`) return { title: "WBD & commercieel", html: commercialAdmin(state) };
  return { title: "Niet gevonden", html: empty("Pagina niet gevonden") };
}

function login(message = "", demoEnabled = false): string { document.title = "Inloggen — Sportpaleis Workspace"; return `<main class="sp-login"><section class="sp-login__brand"><img class="sp-login__logo" src="${SPORTPALEIS_OFFICIAL_LOGO}" alt="Sport 2000 Sportpaleis"><p>Een rustige, gedeelde werkplek voor winkel, webshop, productie en organisatie.</p></section><section class="sp-login__panel"><form data-login-form><p class="sp-eyebrow">BEVEILIGDE PILOTOMGEVING</p><h1>Welkom terug</h1>${message ? `<div class="sp-form-error">${esc(message)}</div>` : ""}<label>E-mailadres<input name="email" type="email" required autocomplete="username"></label><label>Wachtwoord<input name="password" type="password" minlength="12" required autocomplete="current-password"></label><fieldset class="sp-device-choice"><legend>Dit apparaat</legend><label><input type="radio" name="deviceMode" value="SHARED" checked> Gedeeld · kort en vergrendelbaar</label><label><input type="radio" name="deviceMode" value="PERSONAL"> Persoonlijk · langer aangemeld</label></fieldset><button class="sp-button sp-button--primary sp-button--wide">Veilig inloggen</button></form>${demoEnabled ? `<div class="sp-demo-login"><p class="sp-eyebrow">ALLEEN LOKALE REVIEW · DEMO</p><button data-action="demo-login" data-view="store">Winkelmedewerker</button><button data-action="demo-login" data-view="operator">Patrick · Productie</button><button data-action="demo-login" data-view="admin">Kevin · Beheer</button></div>` : ""}</section></main>`; }
function message(error: unknown): string { return error instanceof Error ? error.message : "Handeling mislukt."; }

const loadedProductionFontIds = new Set<string>();
async function activateProductionFonts(app: HTMLElement, state: PilotBootstrap): Promise<void> {
  const requested = new Set([...app.querySelectorAll<HTMLElement>("[data-font-id]")].map(({ dataset }) => dataset.fontId).filter(Boolean) as string[]);
  await Promise.all([...requested].map(async (fontId) => {
    const font = state.productionFonts.find(({ id }) => id === fontId); if (!font) return;
    try {
      if (!loadedProductionFontIds.has(fontId)) { const face = new FontFace(productionFontFamily(fontId), `url("${font.sourceUrl.replaceAll('"', '%22')}")`); await face.load(); document.fonts.add(face); loadedProductionFontIds.add(fontId); }
      app.querySelectorAll<HTMLElement>(`[data-font-id="${CSS.escape(fontId)}"]`).forEach((node) => { node.dataset.fontReady = "true"; node.querySelector<HTMLElement>("[data-font-loading]")?.remove(); });
    } catch { app.querySelectorAll<HTMLElement>(`[data-font-id="${CSS.escape(fontId)}"]`).forEach((node) => { node.dataset.fontReady = "error"; const status = node.querySelector<HTMLElement>("[data-font-loading]"); if (status) status.textContent = "Fontbron kon niet veilig worden geladen."; }); }
  }));
}

